def ev(id,labels,scope,notes,typ='D',verdict='proved',artifacts=None):
 return dict(event_id=id,type=typ,labels=labels,verdict=verdict,scope=scope,derivation=notes,checker=checker,recorded_at=stamp,artifacts=artifacts or [])
